CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL);
INSERT INTO organizations VALUES ('00000000-0000-4000-8000-000000000001','Servicio Express');
CREATE TABLE sources (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations, supplier text NOT NULL, filename text NOT NULL, media_type text NOT NULL, original bytea NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), UNIQUE(tenant_id,id));
CREATE TABLE variants (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations, identity text NOT NULL, brand text NOT NULL, model text NOT NULL, variant text NOT NULL DEFAULT '', markup_type text CHECK(markup_type IN ('percent','fixed')), markup_value numeric(14,2) CHECK(markup_value>=0), UNIQUE(tenant_id,identity), UNIQUE(tenant_id,id));
CREATE TABLE offers (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations, variant_id uuid NOT NULL, supplier text NOT NULL, source_id uuid NOT NULL, cost numeric(14,2) NOT NULL CHECK(cost>0), currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'), terms jsonb NOT NULL DEFAULT '{}', published_at timestamptz NOT NULL DEFAULT now(), superseded_at timestamptz, markup_type text CHECK(markup_type IN ('percent','fixed')), markup_value numeric(14,2) CHECK(markup_value>=0), FOREIGN KEY(tenant_id,variant_id) REFERENCES variants(tenant_id,id), FOREIGN KEY(tenant_id,source_id) REFERENCES sources(tenant_id,id), UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX one_current_offer ON offers(tenant_id,variant_id,supplier,currency) WHERE superseded_at IS NULL;
CREATE TABLE purchases (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations, variant_id uuid NOT NULL, supplier text NOT NULL, unit_cost numeric(14,2) NOT NULL CHECK(unit_cost>0), currency text NOT NULL, occurred_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,variant_id) REFERENCES variants(tenant_id,id));
CREATE TABLE sales (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations, variant_id uuid NOT NULL, unit_price numeric(14,2) NOT NULL CHECK(unit_price>0), currency text NOT NULL, occurred_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,variant_id) REFERENCES variants(tenant_id,id));
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations, actor text NOT NULL, action text NOT NULL, entity_id text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE login_attempts (key text PRIMARY KEY, attempts integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE INDEX offers_lookup ON offers(tenant_id,variant_id,published_at DESC);
CREATE INDEX audit_lookup ON audit_events(tenant_id,created_at DESC);
